import React from "react";

const Stall = () => {
    return (
        <div className="min-h-screen bg-slate-900 flex items-center justify-center overflow-hidden">
            {/* Main Stage Container */}
            <div className="relative w-[500px] h-[500px] flex items-end justify-center">

                {/* Floor (Flat View) */}
                <div className="absolute bottom-0 w-full h-24 bg-slate-800 rounded-t-lg shadow-inner"></div>

                {/* Back Wall (Now centered and flat) */}
                <div className="absolute bottom-24 w-96 h-80 bg-gradient-to-br from-blue-600 to-indigo-800 border-4 border-blue-400 flex flex-col items-center justify-center text-white shadow-2xl z-10">
                    <h2 className="text-4xl font-black tracking-tighter">VANTAGE</h2>
                    <p className="text-xs uppercase tracking-widest opacity-80">Premium Exhibits</p>

                    {/* Decorative Screen on Wall */}
                    <div className="mt-8 w-64 h-32 bg-slate-900 rounded border border-blue-300 flex items-center justify-center overflow-hidden">
                        <div className="w-full h-full bg-blue-500/20 animate-pulse flex items-center justify-center text-[10px] text-blue-300">
                            LIVE STREAMING...
                        </div>
                    </div>
                </div>

                {/* Left Pillar (Formerly Side Wall) */}
                <div className="absolute bottom-24 left-4 w-8 h-80 bg-blue-900 border-l-4 border-blue-400 z-0"></div>

                {/* Right Pillar (Balanced for Front View) */}
                <div className="absolute bottom-24 right-4 w-8 h-80 bg-blue-900 border-r-4 border-blue-400 z-0"></div>

                {/* Front Counter Desk (Centered in front of the wall) */}
                <div className="absolute bottom-12 w-64 h-28 bg-white shadow-2xl flex items-center justify-center border-b-8 border-gray-300 z-30 transition-transform hover:scale-105">
                    <div className="text-center">
                        <div className="text-blue-600 font-bold text-lg italic">RECEPTION</div>
                        <div className="w-12 h-1 bg-blue-600 mx-auto mt-1"></div>
                    </div>
                    {/* Counter Top Edge */}
                    <div className="absolute -top-2 w-full h-2 bg-gray-200"></div>
                </div>

                {/* Floating Interactive Product */}
                <div className="absolute top-10 right-20 w-20 h-20 bg-yellow-400 rounded-full flex items-center justify-center shadow-lg animate-bounce cursor-pointer group z-40">
                    <span className="text-3xl group-hover:scale-125 transition">🎁</span>
                    <div className="absolute -bottom-10 bg-white text-black text-[10px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition whitespace-nowrap font-bold shadow-md">
                        CLICK FOR BROCHURE
                    </div>
                </div>
            </div>

            {/* UI Overlay */}
            <div className="absolute bottom-10 left-10 text-white">
                <h1 className="text-2xl font-bold">Virtual Stall #A-01</h1>
                <p className="text-blue-400">Front Perspective View</p>
            </div>

            <button
                onClick={() => window.history.back()}
                className="absolute top-10 left-10 text-white border border-white/30 px-4 py-2 rounded-full hover:bg-white hover:text-black transition z-50"
            >
                ← Exit Stall
            </button>
        </div>
    );
};

export default Stall;
